def parse_duration(value):
    if not value:
        raise ValueError("Input string cannot be empty.")

    total_seconds = 0
    parts = value.split()

    if not parts:
        raise ValueError("String contains no valid duration terms.")

    for part in parts:
        if not part:
            continue

        # Check for unit and quantity
        unit = part[-1].lower()
        quantity_str = part[:-1]

        try:
            quantity = int(quantity_str)
        except ValueError:
            raise ValueError(f"Non-integer quantity found in term: {part}")

        if unit == 'h':
            total_seconds += quantity * 3600
        elif unit == 'm':
            total_seconds += quantity * 60
        elif unit == 's':
            total_seconds += quantity
        else:
            raise ValueError(f"Unknown unit found in term: {part}")

    return total_seconds

