def group_by_key(rows, key):
    result = {}
    for row in rows:
        # Determine the value to group by, defaulting to None if key is missing
        group_value = row.get(key, None)

        if group_value not in result:
            result[group_value] = []

        # Append the original row dictionary to the list for that key
        result[group_value].append(row)

    return result

