def chunked(iterable, size):
    if size <= 0:
        raise ValueError("size must be greater than 0")

    it = iter(iterable)
    chunks = []
    current_chunk = []

    while True:
        try:
            item = next(it)
            current_chunk.append(item)
        except StopIteration:
            if current_chunk:
                chunks.append(tuple(current_chunk))
            break

    return chunks
